def compute(vars):
    old_berths = vars["v1"]
    added_berths = vars["v2"]

    if old_berths == 0:
        return None

    increase_ratio = added_berths / old_berths
    percentage_increase = increase_ratio * 100

    return {
        "value": percentage_increase,
        "trace": {
            "old_berths": old_berths,
            "added_berths": added_berths,
            "increase_ratio": increase_ratio,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
